import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Calculate correlations between features and outcome
    correlations = []
    for fid in feats.ids:
        col_idx = feats.column(fid)
        corr = np.corrcoef(feats.x[:, col_idx], feats.y)[0, 1]
        correlations.append((fid, abs(corr)))

    # Sort by absolute correlation and take top 10
    correlations.sort(key=lambda x: x[1], reverse=True)
    top_features = [fid for fid, _ in correlations[:10]]

    # Find strong drivers (high t-statistics)
    drivers = []
    for fid in top_features:
        col_idx = feats.column(fid)
        t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, col_idx], feats.x[feats.y==0, col_idx])
        if abs(t_stat) > 3.0:
            drivers.append(fid)
            if len(drivers) >= MAX_DRIVERS:
                break

    # If no strong drivers found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select columns with moderate associations
    columns = []
    for fid in top_features:
        col_idx = feats.column(fid)
        t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, col_idx], feats.x[feats.y==0, col_idx])
        if abs(t_stat) > 1.5:
            columns.append(fid)

    # Remove near-duplicates
    kept_columns = []
    seen = set()

    if len(columns) > 1:
        X_subset = feats.x[:, [feats.column(fid) for fid in columns]]
        corr_matrix = np.corrcoef(X_subset.T)

        for i, fid in enumerate(columns):
            if fid in seen:
                continue
            kept_columns.append(fid)
            seen.add(fid)

            # Mark highly correlated features as seen
            for j in range(i+1, len(columns)):
                if abs(corr_matrix[i, j]) >= 0.6:
                    seen.add(columns[j])
    else:
        kept_columns = columns

    # Simple product term
    products = []
    if len(kept_columns) >= 2:
        products = [(kept_columns[0], kept_columns[1])]

    # Weighted loading based on t-statistics
    loadings = {}
    for i, fid in enumerate(kept_columns[:3]):
        col_idx = feats.column(fid)
        t_stat, _ = stats.ttest_ind(feats.x[feats.y==1, col_idx], feats.x[feats.y==0, col_idx])
        loadings[fid] = abs(t_stat)

    return Design(
        drivers=tuple(drivers),
        columns=tuple(kept_columns),
        products=tuple(products),
        loadings=loadings
    )

